struct Node {
    virtual ~Node() = default;
    virtual std::vector<const Node*> children() const = 0;   // normalized view
};
struct Binary : Node {
    std::unique_ptr<Node> left, right;
    int op;
    std::vector<const Node*> children() const override { return {left.get(), right.get()}; }
};
void walk(const Node& n, const std::function<void(const Node&)>& f) {
    f(n);
    for (const Node* c : n.children()) walk(*c, f);
}

struct Binary;
using Node = std::variant<IntLit, std::unique_ptr<Binary>>;
struct Binary { Node left; int op; Node right; };

std::vector<const Node*> children(const Node& n) {
    return std::visit(overloaded{
        [](const IntLit&)        { return std::vector<const Node*>{}; },
        [](const std::unique_ptr<Binary>& b) { return std::vector<const Node*>{&b->left, &b->right}; }
    }, n);
}

class Expr {
  ExprKind kind;
public:
  explicit Expr(ExprKind k) : kind(k) {}
  ExprKind getKind() const { return kind; }
  virtual child_iterator child_begin() const = 0;   // normalized traversal
  virtual child_iterator child_end() const = 0;
};
class BinaryExpr : public Expr {
public:
  BinaryExpr() : Expr(EK_BinaryExpr) {}
  static bool classof(const Expr* e) { return e->getKind() == EK_BinaryExpr; }
};

